//! Go 1.26 crypto/hpke's test vectors (`testdata/go_vectors.zig`, generated by
//! `tools/gen_go_vectors.py`) driven through this module's public entry points,
//! the way Go's own `TestVectors` drives them:
//!
//! - `rfc9180.json`: RFC 9180 suites (X25519, P-256, P-521; HKDF-SHA256/512;
//!   AES-128/256-GCM, ChaCha20Poly1305 and the export-only AEAD), each pinned as
//!   a SHAKE128 digest over 1000 seal/open rounds of SHAKE128-drawn inputs and
//!   1000 exports of length 0..999 — far more of the AEAD/export surface than
//!   RFC 9180 Appendix A's six messages;
//! - `hpke-pq.json`: draft-ietf-hpke-pq — ML-KEM-512/768/1024, MLKEM768-P256,
//!   MLKEM1024-P384, X-Wing, the SHAKE128/256 and TurboSHAKE128/256 one-stage
//!   KDFs, and P-384 (an external anchor `P384Kem` never had: RFC 9180 publishes
//!   no P-384 vector). Every intermediate the vector carries is compared.
//!
//! Skipped: DHKEM(X448) (0x0021), not implemented (SPEC Backlog). Go itself
//! skips ML-KEM-512 and TurboSHAKE; they run here.

const std = @import("std");
const testing = std.testing;
const go = @import("testdata/go_vectors.zig");
const suite = @import("suite.zig");
const dhkem = @import("dhkem.zig");
const pq = @import("pq.zig");
const kdf = @import("kdf.zig");
const schedule = @import("schedule.zig");
const aesgcm = @import("aesgcm");
const chachapoly = @import("chachapoly");

fn KemOf(comptime id: u16) ?type {
    return switch (id) {
        0x0010 => dhkem.P256Kem,
        0x0011 => dhkem.P384Kem,
        0x0012 => dhkem.P521Kem,
        0x0020 => dhkem.X25519Kem,
        0x0040 => pq.MlKem512Kem,
        0x0041 => pq.MlKem768Kem,
        0x0042 => pq.MlKem1024Kem,
        0x0050 => pq.MlKem768P256Kem,
        0x0051 => pq.MlKem1024P384Kem,
        0x647a => pq.MlKem768X25519Kem,
        else => null,
    };
}

fn KdfOf(comptime id: u16) type {
    return switch (id) {
        0x0001 => kdf.HkdfSha256,
        0x0002 => kdf.HkdfSha384,
        0x0003 => kdf.HkdfSha512,
        0x0010 => kdf.Shake128,
        0x0011 => kdf.Shake256,
        0x0012 => kdf.TurboShake128,
        0x0013 => kdf.TurboShake256,
        else => @compileError("unknown kdf"),
    };
}

fn AeadOf(comptime id: u16) type {
    return switch (id) {
        0x0001 => aesgcm.Aes128Gcm,
        0x0002 => aesgcm.Aes256Gcm,
        0x0003 => chachapoly.ChaCha20Poly1305,
        0xffff => schedule.ExportOnly,
        else => @compileError("unknown aead"),
    };
}

fn unhex(a: std.mem.Allocator, h: []const u8) ![]u8 {
    const b = try a.alloc(u8, h.len / 2);
    _ = try std.fmt.hexToBytes(b, h);
    return b;
}

fn expectHex(a: std.mem.Allocator, want_hex: []const u8, got: []const u8) !void {
    const want = try unhex(a, want_hex);
    try testing.expectEqualSlices(u8, want, got);
}

/// Go's `drawRandomInput`: one length byte, then that many bytes.
fn draw(a: std.mem.Allocator, x: *std.crypto.hash.sha3.Shake128) ![]u8 {
    var l: [1]u8 = undefined;
    x.squeeze(&l);
    const b = try a.alloc(u8, l[0]);
    x.squeeze(b);
    return b;
}

fn check(comptime Kem: type, comptime Kdf: type, comptime Aead: type, comptime v: go.Vector) !void {
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const a = arena_state.allocator();
    const is_pq = @hasDecl(Kem, "Ephemeral");

    // Recipient key: DeriveKeyPair(ikmR) must give pkRm (and skRm).
    var skR: Kem.KeyPair = undefined;
    Kem.deriveKeyPair(&skR, try unhex(a, v.ikmR));
    try expectHex(a, v.pkRm, &skR.public_key);
    if (is_pq) {
        try expectHex(a, v.skRm, &skR.seed);
        var from_seed: Kem.KeyPair = undefined;
        Kem.fromSeed(&from_seed, (try unhex(a, v.skRm))[0..Kem.Nsk]);
        try expectHex(a, v.pkRm, &from_seed.public_key);
    } else if (Kem != dhkem.X25519Kem) {
        try expectHex(a, v.skRm, &skR.secret_key);
    }

    // Sender ephemeral: a DHKEM derives it from ikmE, a pq KEM takes ikmE as
    // its encapsulation randomness.
    var eph: schedule.Ephemeral(Kem) = undefined;
    if (is_pq) {
        const e = try unhex(a, v.ikmE);
        try testing.expectEqual(@sizeOf(Kem.Ephemeral), e.len);
        @memcpy(std.mem.asBytes(&eph), e);
    } else Kem.deriveKeyPair(&eph, try unhex(a, v.ikmE));

    const info = try unhex(a, v.info);
    var s: schedule.Setup(Kem, Aead, Kdf) = undefined;
    try schedule.setupBaseSDeterministic(Kem, Aead, Kdf, &s, skR.public_key, &eph, info);
    try expectHex(a, v.enc, &s.enc);
    var r: schedule.Context(Aead, Kdf) = undefined;
    try schedule.setupBaseR(Kem, Aead, Kdf, &r, s.enc, &skR, info);

    if (v.key.len != 0) try expectHex(a, v.key, &s.context.key);
    if (v.base_nonce.len != 0) try expectHex(a, v.base_nonce, &s.context.base_nonce);
    if (v.exporter_secret.len != 0) try expectHex(a, v.exporter_secret, &s.context.exporter_secret);
    try testing.expectEqualSlices(u8, &s.context.key, &r.key);
    try testing.expectEqualSlices(u8, &s.context.base_nonce, &r.base_nonce);
    try testing.expectEqualSlices(u8, &s.context.exporter_secret, &r.exporter_secret);

    const suite_id = suite.suiteId(Kem.kem_id, Kdf.kdf_id, v.aead_id);

    if (Aead != schedule.ExportOnly) {
        if (v.encryptions_accumulated.len != 0) {
            var source = std.crypto.hash.sha3.Shake128.init(.{});
            var sink = std.crypto.hash.sha3.Shake128.init(.{});
            for (0..1000) |_| {
                const aad = try draw(a, &source);
                const pt = try draw(a, &source);
                const ct = try a.alloc(u8, pt.len + Aead.tag_length);
                try s.context.seal(aad, pt, ct);
                sink.update(ct);
                const back = try a.alloc(u8, pt.len);
                try r.open(aad, ct, back);
                try testing.expectEqualSlices(u8, pt, back);
            }
            var acc: [16]u8 = undefined;
            sink.squeeze(&acc);
            try expectHex(a, v.encryptions_accumulated, &acc);
        } else {
            for (v.encryptions) |e| {
                const pt = try unhex(a, e.pt);
                const aad = try unhex(a, e.aad);
                try expectHex(a, e.nonce, &schedule.computeNonce(Aead.nonce_length, s.context.base_nonce, s.context.seq));
                const ct = try a.alloc(u8, pt.len + Aead.tag_length);
                try s.context.seal(aad, pt, ct);
                try expectHex(a, e.ct, ct);
                const back = try a.alloc(u8, pt.len);
                try r.open(aad, ct, back);
                try testing.expectEqualSlices(u8, pt, back);
            }
        }
    }

    if (v.exports_accumulated.len != 0) {
        var source = std.crypto.hash.sha3.Shake128.init(.{});
        var sink = std.crypto.hash.sha3.Shake128.init(.{});
        for (0..1000) |l| {
            const ctx = try draw(a, &source);
            const value = try a.alloc(u8, l);
            try s.context.exportSecret(&suite_id, ctx, value);
            sink.update(value);
            const again = try a.alloc(u8, l);
            try r.exportSecret(&suite_id, ctx, again);
            try testing.expectEqualSlices(u8, value, again);
        }
        var acc: [16]u8 = undefined;
        sink.squeeze(&acc);
        try expectHex(a, v.exports_accumulated, &acc);
    } else {
        for (v.exports) |e| {
            const value = try a.alloc(u8, e.len);
            try s.context.exportSecret(&suite_id, try unhex(a, e.context), value);
            try expectHex(a, e.value, value);
        }
    }

    // The single-shot pair agrees with the setup layer (pq KEMs included).
    if (Aead != schedule.ExportOnly) {
        const pt = "single-shot";
        var ct: [pt.len + Aead.tag_length]u8 = undefined;
        const sealed = try schedule.sealBaseDeterministic(Kem, Aead, Kdf, skR.public_key, &eph, info, "aad", pt, &ct);
        try testing.expectEqualSlices(u8, &s.enc, &sealed.enc);
        var back: [pt.len]u8 = undefined;
        try schedule.openBase(Kem, Aead, Kdf, sealed.enc, &skR, info, "aad", &ct, &back);
        try testing.expectEqualStrings(pt, &back);
    }
}

test "Go crypto/hpke vectors: rfc9180.json + hpke-pq.json through setupBaseS/R, seal/open, export" {
    var ran: usize = 0;
    inline for (go.vectors) |v| {
        if (comptime KemOf(v.kem_id)) |Kem| {
            comptime std.debug.assert(v.mode == 0);
            check(Kem, KdfOf(v.kdf_id), AeadOf(v.aead_id), v) catch |e| {
                std.debug.print("vector {s} kem 0x{x:0>4} kdf 0x{x:0>4} aead 0x{x:0>4} failed\n", .{ v.source, v.kem_id, v.kdf_id, v.aead_id });
                return e;
            };
            ran += 1;
        }
    }
    // 24 rfc9180 + 13 hpke-pq, minus the X448 one.
    try testing.expectEqual(@as(usize, 36), ran);
}

test "pq KEMs: psk mode round-trips over a one-stage and a two-stage KDF" {
    var threaded = std.Io.Threaded.init(testing.allocator, .{});
    defer threaded.deinit();
    const io = threaded.io();
    const psk = "0123456789abcdef0123456789abcdef";
    inline for (.{ pq.MlKem768Kem, pq.MlKem768X25519Kem, pq.MlKem1024P384Kem }) |Kem| {
        inline for (.{ kdf.Shake256, kdf.HkdfSha256 }) |Kdf| {
            var skR: Kem.KeyPair = undefined;
            Kem.generateKeyPair(&skR, io);
            var s: schedule.Setup(Kem, aesgcm.Aes128Gcm, Kdf) = undefined;
            try schedule.setupPskS(Kem, aesgcm.Aes128Gcm, Kdf, &s, skR.public_key, io, "info", psk, "id");
            var r: schedule.Context(aesgcm.Aes128Gcm, Kdf) = undefined;
            try schedule.setupPskR(Kem, aesgcm.Aes128Gcm, Kdf, &r, s.enc, &skR, "info", psk, "id");
            try testing.expectEqualSlices(u8, &s.context.key, &r.key);
            try testing.expectEqualSlices(u8, &s.context.base_nonce, &r.base_nonce);
            try testing.expectEqualSlices(u8, &s.context.exporter_secret, &r.exporter_secret);
            // A different psk_id gives a different context.
            var r2: schedule.Context(aesgcm.Aes128Gcm, Kdf) = undefined;
            try schedule.setupPskR(Kem, aesgcm.Aes128Gcm, Kdf, &r2, s.enc, &skR, "info", psk, "id2");
            try testing.expect(!std.mem.eql(u8, &r.key, &r2.key));
        }
    }
}
